# =====================================================================
#  legal.map - phishing phrases for law firms and legal departments
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : case files and court documents behind a link, contracts /
#           settlements to e-sign, escrow and client-fund account
#           changes (BEC), cease-and-desist and infringement claims,
#           debt collection notices, inheritance / beneficiary /
#           next-of-kin advance-fee scams, fake retainer invoices
#
#  Avoided: "contract draft attached", "court hearing scheduled",
#           "meeting with the client", because law firms exchange real
#           ones every day.
# =====================================================================

# ===== English =====
# Case files / documents
/(view|download|review|access)\s+(the\s+)?(case\s+files?|court\s+documents?|legal\s+documents?|case\s+materials?)\s+(here|online|via\s+(the\s+)?(secure\s+)?link|on\s+our\s+portal)/i
/(legal|case)\s+documents?\s+(have\s+been|has\s+been)\s+(shared|uploaded|sent)\s+(with\s+you\s+)?(via|through|on)\s+(a\s+)?(secure\s+)?(portal|link|server)/i
# E-signing
/(please\s+)?(review\s+and\s+)?(sign|e-?sign)\s+(the\s+)?(settlement|agreement|contract|power\s+of\s+attorney|nda)\s+(electronically\s+)?(via|using|through|at)\s+(the\s+)?(link|portal)/i
/(settlement|agreement|contract)\s+(is\s+)?(awaiting|pending)\s+your\s+(e-?)?signature/i
# Escrow / client funds (BEC)
/(escrow|trust|client)\s+account\s+(details\s+)?(have\s+|has\s+)?(changed|been\s+updated)/i
/(wire|transfer)\s+(the\s+)?(settlement|closing|escrow)\s+(funds|amount|payment)\s+to\s+(the\s+)?(new|following|updated)\s+account/i
/(updated|new)\s+(wiring|wire)\s+instructions\s+for\s+(the\s+)?(closing|settlement|escrow|transaction)/i
# Claims / notices
/(cease\s+and\s+desist|dmca\s+takedown)\s+(notice|letter|order)/i
/(final\s+)?(notice\s+of\s+)?(legal\s+action|litigation)\s+(will\s+be\s+taken|before\s+court)\s+(unless|if)/i
/(debt\s+collection|collection\s+agency)\s+(notice|final\s+demand)/i
# Inheritance / advance-fee
/(you\s+(are|have\s+been\s+named)\s+(as\s+)?)(the\s+)?(sole\s+)?(beneficiary|next\s+of\s+kin|heir)\s+(of|to)/i
/(unclaimed|dormant)\s+(inheritance|estate|funds|fortune)\s+(of|worth|valued)/i
/(late|deceased)\s+(client|customer|mr\.?|mrs\.?)\s+[^.]{0,40}(left|deposited)\s+(a\s+)?(sum|fund|amount)/i
# Retainer / fees
/(retainer|legal)\s+(fee|invoice)\s+(is\s+)?(overdue|outstanding|unpaid)[,.:]?\s+(view|pay|via|online)/i

# ===== Spanish =====
/(vea|descargue|acceda\s+a)\s+(el\s+)?(expediente|documentos?\s+(del\s+caso|judiciales|legales))\s+(aqu[íi]|en\s+l[íi]nea|en\s+el\s+enlace)/iu
/firme\s+(el\s+)?(acuerdo|contrato|poder)\s+(electr[óo]nicamente\s+)?(en|mediante)\s+el\s+enlace/iu
/(nuevas|actualizadas)\s+instrucciones\s+de\s+(pago|transferencia)\s+para\s+(el\s+)?(cierre|acuerdo)/iu
/(usted\s+es|ha\s+sido\s+nombrado)\s+(el\s+)?([úu]nico\s+)?(beneficiario|heredero)/iu

# ===== German =====
/(sehen\s+sie|laden\s+sie)\s+(die\s+)?(fallakte|gerichtsakte|prozessunterlagen|rechtsdokumente)\s+(hier|online|[üu]ber\s+den\s+link)/iu
/(unterzeichnen|signieren)\s+sie\s+(den\s+|die\s+)?(vergleich|vertrag|vollmacht)\s+([üu]ber\s+den\s+link|online)/iu
/(ge[äa]nderte|neue)\s+(treuhand|anderkonto)(konto)?\s*-?\s*(daten|verbindung)/iu
/sie\s+sind\s+(der\s+)?(alleinige[r]?\s+)?(beg[üu]nstigte[r]?|erbe)/iu

